module HonestTest

using Test
using KernelSmoothing
using KernelSmoothing: _cvb, _honestM
using Distributions: Normal, cdf as ncdf

# reference values from RDHonest 1.0.2, generated by data/honest_golden.R
include(joinpath(@__DIR__, "data", "honest_golden.jl"))

const I = 1:400
const X = round.(mod.(I .* 0.6180339887498949, 1), digits = 2)
const Y = sin.(2π .* X) .+ 0.3 .* sin.(7.3 .* I)
const K = Dict("triangular" => TriangularKernel(), "epanechnikov" => EpanechnikovKernel(), "uniform" => UniformKernel())

@testset "agrees with RDHonest" begin
  for c in RDHONEST
    m = fit(LocalPolynomialRegression, X, Y; kernel = K[c.kernel], bandwidth = c.h, points = [c.x0],
            vce = HCVariance(0), minobs = 0)
    @test m.estimate[1] ≈ c.estimate rtol = 1e-10
    @test m.se[1] ≈ c.se rtol = 1e-10
    @test worstcasebias(m, c.M)[1] ≈ c.maxbias rtol = 1e-10
    @test confint(m; method = Honest(c.M)) ≈ [c.lower c.upper] rtol = 1e-10
  end
  # RDHonest searches with a preliminary variance estimate; the length is flat near the optimum
  d = SmoothingData(X, Y)
  s = selectbandwidth(FLCIOptimal(40), d, TriangularKernel(); points = [0.3], vce = HCVariance(0), minobs = 0)
  @test s.h[1] ≈ RDHONEST_FLCI.h rtol = 0.05
  m = fit(LocalPolynomialRegression, d; kernel = TriangularKernel(), bandwidth = s.h, points = [0.3],
          vce = HCVariance(0), minobs = 0)
  @test confint(m; method = Honest(40)) ≈ [RDHONEST_FLCI.lower RDHONEST_FLCI.upper] rtol = 2e-3
end

@testset "critical values" begin
  # also for levels below 1/2, where the quantile of |N(t, 1)| can be below t
  for t in (0.0, 0.5, 1.0, 3.0, 30.0), level in (0.05, 0.3, 0.45, 0.5, 0.9, 0.95, 0.999)
    c = _cvb(t, level)
    @test ncdf(Normal(), c - t) - ncdf(Normal(), -c - t) ≈ level atol = 1e-12
  end
  @test _cvb(0.0, 0.95) ≈ 1.959963984540054 rtol = 1e-10
  @test _cvb(1.0, 0.95) ≈ 2.646146 rtol = 1e-6   # RDHonest's CVb(1)
end

@testset "worst-case bias" begin
  # a function at the edge of the Taylor class, (M/2)(x - x0)² sign(ℓ), attains the bias
  m = fit(LocalPolynomialRegression, X, Y; bandwidth = 0.15, points = [0.4], vce = HCVariance(0), minobs = 0)
  M = 25.0
  B = worstcasebias(m, M)[1]
  # the weights ℓ by their definition, through two fits that differ by a known function
  function ℓ(x0, h, xs)
    u = (xs .- x0) ./ h
    w = EpanechnikovKernel().(u)
    S0, S1, S2 = sum(w), sum(w .* u), sum(w .* u .^ 2)
    return w .* (S2 .- S1 .* u) ./ (S0 * S2 - S1^2)
  end
  l = ℓ(0.4, 0.15, X)
  @test B ≈ M / 2 * sum(abs.(l) .* (X .- 0.4) .^ 2) rtol = 1e-10
  f = M / 2 .* (X .- 0.4) .^ 2 .* sign.(l)
  m2 = fit(LocalPolynomialRegression, X, Y .+ f; bandwidth = 0.15, points = [0.4], vce = HCVariance(0), minobs = 0)
  @test m2.estimate[1] - m.estimate[1] ≈ B rtol = 1e-10
  # wider than the conventional interval, and with the bias-corrected estimate around its own weights
  ci, cc = confint(m; method = Honest(M)), confint(m; method = Conventional())
  @test ci[1] < cc[1] && ci[2] > cc[2]
  cb = confint(m; method = Honest(M; biascorrected = true))
  @test (cb[1] + cb[2]) / 2 ≈ m.estimate_bc[1]
  @test stderror(m; method = Honest(M)) == m.se && stderror(m; method = Honest(M; biascorrected = true)) == m.se_rbc
  # derivatives: the class bounds the derivative of order p + 1
  m3 = fit(LocalPolynomialRegression, X, Y; degree = 2, derivative = 1, bandwidth = 0.2, points = [0.5], minobs = 0)
  @test worstcasebias(m3, 100.0)[1] > 0
end

@testset "rule of thumb and arguments" begin
  d = SmoothingData(X, Y)
  # the second derivative of sin(2πx) is at most 4π² ≈ 39.5; the quartic pilot is rougher
  @test 10 < _honestM(d, 1) < 200
  m = fit(LocalPolynomialRegression, d; bandwidth = 0.15, points = [0.4])
  @test confint(m; method = Honest()) == confint(m; method = Honest(_honestM(d, 1)))
  @test_throws ArgumentError Honest(-1)
  @test_throws ArgumentError Honest(:big)
  @test_throws ArgumentError FLCIOptimal(1.0; gridsize = 2)
  @test_throws ArgumentError confband(m; method = Honest(10))
  @test_throws ArgumentError confint(fit(PointwiseDensity, X; bandwidth = 0.2); method = Honest(10))
  @test fit(LocalPolynomialRegression, d; bandwidth = FLCIOptimal(20), points = [0.3, 0.6]).selection.rule == FLCIOptimal(20)
  # the search does not go below 21 observations, where residual-based standard errors
  # collapse with the window, even without a floor on the fit
  s = selectbandwidth(FLCIOptimal(1e4), d, EpanechnikovKernel(); points = [0.3, 0.6], vce = HCVariance(0), minobs = 0)
  @test all(s.h .>= [knn_distance(d, c, 21) for c in (0.3, 0.6)])
  # with few distinct values the global fit has a lower order, and with p + 1 none
  xd = repeat([1.0, 2.0, 3.0, 4.0], inner = 25)
  @test isfinite(_honestM(SmoothingData(xd, xd .^ 2 .+ 0.1 .* sin.(1:100)), 1))
  @test_throws ArgumentError _honestM(SmoothingData(repeat([1.0, 2.0], 50), rand(100)), 1)
end

end
